// @nodegx:generated by `nodegx export --target html` — Story/Choice.
import { batch, value } from '../lib/core.js';
import { bindText, el, life } from '../lib/dom.js';

/**
 * One choice
 *
 * Draws into `element` (before `before`, when given). `inputs` are what the parent sets:
 * `label`, `goto`, `gives`, and the callbacks `onPicked`.
 * Returns `update(inputs)` to change them, `outputs`, and `destroy()` to take it off the page.
 */
export function mountChoice(element, inputs = {}, before) {
  const l = life();
  const given = Object.assign({}, inputs);
  const input = { label: value(inputs['label']), goto: value(inputs['goto']), gives: value(inputs['gives']) };

  const chRow = el(element, 'div', 'Choice-chRow story-choice pressable', undefined, before);
  const chMark = el(chRow, 'p', 'Choice-chMark', '→');
  const chLabel = el(chRow, 'p', 'Choice-chLabel');
  bindText(l, chLabel, function () { return input.label.get(); });
  chRow.addEventListener('click', function () {
    if (given.onPicked) given.onPicked();
  });

  return {
    update(next) {
      Object.assign(given, next);
      batch(function () {
        if ('label' in next) input.label.set(next['label']);
        if ('goto' in next) input.goto.set(next['goto']);
        if ('gives' in next) input.gives.set(next['gives']);
      });
    },
    outputs: {},
    destroy() {
      l.destroy();
      chRow.remove();
    }
  };
}
